// src/components/Socket.jsx
import React, { useEffect, useState } from "react";
import socket from "../socket"; // shared socket instance

export default function Socket({ currentUser }) {
  const [users, setUsers] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [text, setText] = useState("");
  const [search, setSearch] = useState("");

  useEffect(() => {
    if (!currentUser) return;

    socket.connect();
    socket.emit("set username", currentUser);

    socket.on("active users", (userList) => {
      setUsers(userList.filter((u) => u !== currentUser));
    });

    socket.on("load messages", (msgs) => {
      setMessages(msgs);
    });

    socket.on("private message", (msg) => {
      setMessages((prev) => [...prev, msg]);
    });

    socket.on("delete message locally", (id) => {
      setMessages((prev) => prev.filter((m) => m._id !== id));
    });

    socket.on("delete message globally", (id) => {
      setMessages((prev) => prev.filter((m) => m._id !== id));
    });

    return () => {
      socket.off("active users");
      socket.off("load messages");
      socket.off("private message");
      socket.off("delete message locally");
      socket.off("delete message globally");
    };
  }, [currentUser]);

  const sendMessage = (e) => {
    e.preventDefault();
    if (!text || !selectedUser) return;

    socket.emit("private message", { to: selectedUser, content: text });
    setText("");
  };

  const deleteForMe = (id) => {
    socket.emit("delete message for me", { id });
  };

  const deleteForEveryone = (id) => {
    socket.emit("delete message for everyone", id);
  };

  const filteredUsers = users.filter((u) =>
    u.toLowerCase().includes(search.toLowerCase())
  );

  const chat = messages.filter(
    (m) =>
      (m.from === currentUser && m.to === selectedUser) ||
      (m.from === selectedUser && m.to === currentUser)
  );

  return (
    <div style={styles.container}>
      <h2 style={styles.header}>💬 Chat</h2>

      <input
        style={styles.input}
        placeholder="Search users..."
        value={search}
        onChange={(e) => setSearch(e.target.value)}
      />
      <div style={styles.userList}>
        {filteredUsers.length === 0 ? (
          <p style={styles.noUser}>No users found.</p>
        ) : (
          filteredUsers.map((u) => (
            <div
              key={u}
              onClick={() => setSelectedUser(u)}
              style={{
                ...styles.userItem,
                backgroundColor: selectedUser === u ? "#e0e0ff" : "#f5f5f5",
              }}
            >
              {u}
            </div>
          ))
        )}
      </div>

      {selectedUser && (
        <>
          <div style={styles.chatBox}>
            {chat.map((msg) => (
              <div
                key={msg._id}
                style={{
                  ...styles.msg,
                  alignSelf: msg.from === currentUser ? "flex-end" : "flex-start",
                  backgroundColor: msg.from === currentUser ? "#d1e7dd" : "#f8d7da",
                }}
              >
                <div style={{ fontSize: "0.9em" }}>{msg.content}</div>
                <div style={{ fontSize: "0.7em", color: "#555" }}>
                  {new Date(msg.timestamp).toLocaleString()}
                </div>
                <div style={styles.msgActions}>
                  <button onClick={() => deleteForMe(msg._id)}>🗑️ Me</button>
                  {msg.from === currentUser && (
                    <button onClick={() => deleteForEveryone(msg._id)}>❌ All</button>
                  )}
                </div>
              </div>
            ))}
          </div>

          <form onSubmit={sendMessage} style={styles.form}>
            <input
              style={styles.msgInput}
              placeholder="Type message..."
              value={text}
              onChange={(e) => setText(e.target.value)}
            />
            <button type="submit" style={styles.sendBtn}>➤</button>
          </form>
        </>
      )}
    </div>
  );
}

const styles = {
  container: {
    marginTop: 30,
    padding: 20,
    backgroundColor: "#fff",
    borderRadius: 10,
    maxWidth: 600,
    margin: "30px auto",
    boxShadow: "0 0 10px rgba(0,0,0,0.1)",
  },
  header: {
    textAlign: "center",
    marginBottom: 10,
  },
  input: {
    width: "100%",
    padding: 8,
    marginBottom: 10,
    borderRadius: 5,
    border: "1px solid #ccc",
  },
  userList: {
    maxHeight: 100,
    overflowY: "auto",
    marginBottom: 10,
    border: "1px solid #ccc",
    borderRadius: 5,
  },
  noUser: {
    padding: 8,
    textAlign: "center",
    color: "#888",
  },
  userItem: {
    padding: 8,
    cursor: "pointer",
    borderBottom: "1px solid #eee",
  },
  chatBox: {
    minHeight: 150,
    maxHeight: 300,
    overflowY: "auto",
    display: "flex",
    flexDirection: "column",
    gap: 5,
    marginBottom: 10,
    padding: 10,
    backgroundColor: "#f9f9f9",
    borderRadius: 5,
    border: "1px solid #ccc",
  },
  msg: {
    padding: 10,
    borderRadius: 10,
    maxWidth: "75%",
    position: "relative",
  },
  msgActions: {
    display: "flex",
    gap: 5,
    marginTop: 5,
    fontSize: "0.75em",
  },
  form: {
    display: "flex",
    gap: 10,
  },
  msgInput: {
    flex: 1,
    padding: 8,
    borderRadius: 5,
    border: "1px solid #ccc",
  },
  sendBtn: {
    padding: "0 16px",
    backgroundColor: "#4a90e2",
    color: "white",
    border: "none",
    borderRadius: 5,
    cursor: "pointer",
  },
};
